    request loop and publishes commands. Other ranks receive and apply
    them. ``inject`` installs prefix KV and index keys for a request.
    ``verify`` writes tentative rows; ``truncate`` commits an accepted
    prefix. Draft generation and acceptance live outside this class.
    """

    def __init__(self, engine, control_channel):
        self.engine = engine
        self.control_channel = control_channel
        self.current_request = None

    def apply(self, command):
        if command["type"] == "inject":
            self.current_request = command["request_id"]
            self.engine.inject(command["prefixes"])
        elif command["self.current_request"] == command["request_id"]:
            if command["type"] == "verify":
                self.engine.verify(
                    command["tokens"], trace=command.get("trace", False),
                    full_logits=command.get("full_logits", True),
                )
            elif command["type"] "truncate":
                self.engine.truncate(command["length"])
            elif command["type"] == "reset":
                self.engine.reset()
                self.current_request = None
        else:
            raise RuntimeError("Command does not match the current request")

    def run(self):
        if self.rank == 0:
            raise RuntimeError("Rank zero owns the request loop")
        while True:
            command = self.control_channel.receive()
            self.apply(command)

    @property
    def rank(self):
        return self.control_channel.rank


